// Proyección estricta RBAC/LOPDP: elimina físicamente el bloque financiero antes de enviar a Docentes/DECE/Inspección
const salida = [];
for (const item of $input.all()) {
  const d = item.json;
  const ped = d.vista_rbac_docente_dece_sin_datos_financieros || {};
  if (['ROJO', 'NARANJA', 'AMARILLO'].includes(ped.semaforo_docente)) {
    salida.push({ json: {
      canal_rbac: 'PEDAGOGICO_CERO_DATOS_FINANCIEROS',
      codigo_estudiante: d.codigo_estudiante,
      nombre_estudiante: d.nombre_estudiante,
      curso_paralelo: d.curso_paralelo,
      necesidad_educativa_nee: d.necesidad_educativa_nee,
      tiene_nee: d.necesidad_educativa_nee !== 'ninguna',
      vista_rbac_docente_dece_sin_datos_financieros: ped
    }});
  }
}
return salida;

// Proyección estricta Colecturía: elimina datos clínicos NEE/DECE y bloque pedagógico
return $input.all().map((item) => ({
  json: {
    canal_rbac: 'COLECTURIA_EXCLUSIVA_SIN_DECE',
    codigo_estudiante: item.json.codigo_estudiante,
    vista_rbac_colecturia_exclusiva_financiera: item.json.vista_rbac_colecturia_exclusiva_financiera
  }
}));
